/**
 * Cost API Client — BATCH-18/TASK-01
 *
 * Typed functions for all 5 cost endpoints.
 * Endpoint shapes from backend/api/routes/costs.py:
 *   GET /costs/summary     → {total_cost_usd, total_tokens, event_count}
 *   GET /costs/by-provider → {provider_name: {cost_usd, input_tokens, output_tokens, calls}}
 *   GET /costs/by-stage    → {stage_name: {cost_usd, input_tokens, output_tokens, calls}}
 *   GET /costs/by-model    → {model_name: {cost_usd, input_tokens, output_tokens, calls}}
 *   GET /costs/run/{id}    → {run_id, summary, by_provider, by_stage}
 */

import { apiFetch } from "./client";

// ── Types ────────────────────────────────────────────────────────

export interface CostSummary {
  total_cost_usd: number;
  total_tokens: number;
  event_count: number;
}

export interface BreakdownEntry {
  cost_usd: number;
  input_tokens: number;
  output_tokens: number;
  calls: number;
}

/** Dict keyed by provider name */
export type ProviderBreakdown = Record<string, BreakdownEntry>;

/** Dict keyed by stage name */
export type StageBreakdown = Record<string, BreakdownEntry>;

/** Dict keyed by model name */
export type ModelBreakdown = Record<string, BreakdownEntry>;

export interface RunCostBreakdown {
  run_id: string;
  summary: CostSummary;
  by_provider: ProviderBreakdown;
  by_stage: StageBreakdown;
}

// ── API Functions ────────────────────────────────────────────────

export function getCostSummary(): Promise<CostSummary> {
  return apiFetch<CostSummary>("/costs/summary");
}

export function getCostByProvider(): Promise<ProviderBreakdown> {
  return apiFetch<ProviderBreakdown>("/costs/by-provider");
}

export function getCostByStage(): Promise<StageBreakdown> {
  return apiFetch<StageBreakdown>("/costs/by-stage");
}

export function getCostByModel(): Promise<ModelBreakdown> {
  return apiFetch<ModelBreakdown>("/costs/by-model");
}

export function getRunCostBreakdown(runId: string): Promise<RunCostBreakdown> {
  return apiFetch<RunCostBreakdown>(`/costs/run/${runId}`);
}

import { API_PREFIX } from "@/lib/constants";

export class ApiError extends Error {
  constructor(
    public status: number,
    public detail: string,
  ) {
    super(detail);
    this.name = "ApiError";
  }
}

function getBaseUrl(): string {
  return localStorage.getItem("erock_api_url") || "";
}

function getApiKey(): string {
  return localStorage.getItem("erock_api_key") || "";
}

export async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...(options?.headers as Record<string, string> | undefined),
  };
  const key = getApiKey();
  if (key) {
    headers["X-API-Key"] = key;
  }

  const res = await fetch(`${getBaseUrl()}${API_PREFIX}${path}`, {
    ...options,
    headers,
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({ detail: res.statusText }));
    throw new ApiError(res.status, body.detail || body.error || res.statusText);
  }

  if (res.status === 204) return undefined as T;
  return res.json();
}

/** Test backend connectivity via /health endpoint. */
export async function testConnection(baseUrl?: string): Promise<{ ok: true; version: string } | { ok: false; error: string }> {
  try {
    const base = baseUrl ?? getBaseUrl();
    const res = await fetch(`${base}/health`, {
      method: "GET",
      headers: { "Content-Type": "application/json" },
    });
    if (!res.ok) {
      return { ok: false, error: `HTTP ${res.status}` };
    }
    const data = await res.json();
    return { ok: true, version: data.version ?? "unknown" };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

/** Detailed status response from /api/v1/status/detailed. */
export interface DetailedStatus {
  version: string;
  provider: string;
  db_status: string;
}

/** Fetch detailed status from the backend. */
export async function getDetailedStatus(): Promise<DetailedStatus> {
  return apiFetch<DetailedStatus>("/status/detailed");
}

export function sseUrl(path: string): string {
  const base = getBaseUrl() || window.location.origin;
  const key = getApiKey();
  const separator = path.includes("?") ? "&" : "?";
  const auth = key ? `${separator}api_key=${encodeURIComponent(key)}` : "";
  return `${base}${API_PREFIX}${path}${auth}`;
}

